<?php
declare(strict_types=1);
namespace TNL\Contacts;
final class Book {
 public static function init(\PDO $db): void {
  $db->exec("CREATE TABLE IF NOT EXISTS address_contacts(id INTEGER PRIMARY KEY,owner TEXT NOT NULL,owner_name TEXT NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,company TEXT NOT NULL,job_title TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',private INTEGER NOT NULL DEFAULT 0,search_text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
  CREATE TABLE IF NOT EXISTS contact_access(contact_id INTEGER NOT NULL,principal TEXT NOT NULL,requester_name TEXT NOT NULL,status TEXT NOT NULL,requested_at TEXT NOT NULL,decided_at TEXT,seen INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(contact_id,principal));
  CREATE INDEX IF NOT EXISTS idx_contacts_owner ON address_contacts(owner);
  CREATE INDEX IF NOT EXISTS idx_contact_requests ON contact_access(status,contact_id)");
 }
 public static function normalized(string $value): string {
  if(function_exists('iconv')){$ascii=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);if($ascii!==false)$value=$ascii;}
  return strtolower(preg_replace('/[^a-zA-Z0-9@.]+/','',trim($value)));
 }
 private static function text(array $input,string $key,int $limit,bool $required=true): string {
  $value=trim((string)($input[$key]??''));if(($required&&$value==='')||strlen($value)>$limit||!preg_match('//u',$value)||preg_match('/[\x00-\x1f\x7f]/',$value))throw new \InvalidArgumentException('Revisa el campo '.$key.'.');return $value;
 }
 public static function save(\PDO $db,array $who,int $id,array $input): int {
  self::init($db);$first=self::text($input,'first_name',100);$last=self::text($input,'last_name',100);$company=self::text($input,'company',180);$job=self::text($input,'job_title',180);$email=self::text($input,'email',254);$phone=self::text($input,'phone',60,false);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new \InvalidArgumentException('Dirección de correo inválida.');
  $private=!empty($input['private'])?1:0;$now=gmdate('c');$search=self::normalized($first.' '.$last.' '.$company.' '.$job);
  if($id>0){self::owned($db,$who,$id);$q=$db->prepare('UPDATE address_contacts SET first_name=?,last_name=?,company=?,job_title=?,email=?,phone=?,private=?,search_text=?,updated_at=? WHERE id=? AND owner=?');$q->execute([$first,$last,$company,$job,$email,$phone,$private,$search,$now,$id,$who['principal']]);}
  else{$q=$db->prepare('INSERT INTO address_contacts(owner,owner_name,first_name,last_name,company,job_title,email,phone,private,search_text,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$who['principal'],$who['name'],$first,$last,$company,$job,$email,$phone,$private,$search,$now,$now]);$id=(int)$db->lastInsertId();}
  return $id;
 }
 private static function raw(\PDO $db,int $id): array {self::init($db);$q=$db->prepare('SELECT * FROM address_contacts WHERE id=?');$q->execute([$id]);$c=$q->fetch(\PDO::FETCH_ASSOC);if(!$c)throw new \InvalidArgumentException('Contacto no disponible.');return $c;}
 public static function owned(\PDO $db,array $who,int $id): array {$c=self::raw($db,$id);if($c['owner']!==$who['principal'])throw new \InvalidArgumentException('Solo el propietario puede administrar este contacto.');return $c;}
 private static function canRead(\PDO $db,array $who,array $c): bool {if(!$c['private']||$c['owner']===$who['principal'])return true;$q=$db->prepare("SELECT 1 FROM contact_access WHERE contact_id=? AND principal=? AND status='granted'");$q->execute([$c['id'],$who['principal']]);return (bool)$q->fetchColumn();}
 private static function visible(\PDO $db,array $who,array $c): array {$c['can_read']=self::canRead($db,$who,$c);$c['can_manage']=$c['owner']===$who['principal'];if(!$c['can_read']){$c['email']=null;$c['phone']=null;}$q=$db->prepare('SELECT status FROM contact_access WHERE contact_id=? AND principal=?');$q->execute([$c['id'],$who['principal']]);$c['access_status']=$q->fetchColumn()?:'';unset($c['search_text']);return $c;}
 public static function read(\PDO $db,array $who,int $id): array {return self::visible($db,$who,self::raw($db,$id));}
 public static function search(\PDO $db,array $who,string $query='',int $page=1,int $limit=20): array {
  self::init($db);if(strlen($query)>200)throw new \InvalidArgumentException('Búsqueda demasiado larga.');$limit=max(1,min(100,$limit));$page=max(1,min(100000,$page));$term=self::normalized($query);$literal='%'.str_replace(['!','%','_'],['!!','!%','!_'],trim($query)).'%';
  $sql="SELECT c.* FROM address_contacts c WHERE (?='' OR c.search_text LIKE ? ESCAPE '!' OR ((c.private=0 OR c.owner=? OR EXISTS(SELECT 1 FROM contact_access a WHERE a.contact_id=c.id AND a.principal=? AND a.status='granted')) AND (c.email LIKE ? ESCAPE '!' OR c.phone LIKE ? ESCAPE '!'))) ORDER BY c.last_name COLLATE NOCASE,c.first_name COLLATE NOCASE,c.id LIMIT ? OFFSET ?";
  $q=$db->prepare($sql);$q->bindValue(1,$term);$q->bindValue(2,'%'.$term.'%');$q->bindValue(3,$who['principal']);$q->bindValue(4,$who['principal']);$q->bindValue(5,$literal);$q->bindValue(6,$literal);$q->bindValue(7,$limit+1,\PDO::PARAM_INT);$q->bindValue(8,($page-1)*$limit,\PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll(\PDO::FETCH_ASSOC);$more=count($rows)>$limit;return ['rows'=>array_map(fn($c)=>self::visible($db,$who,$c),array_slice($rows,0,$limit)),'more'=>$more,'page'=>$page];
 }
 public static function request(\PDO $db,array $who,int $id): void {
  $c=self::raw($db,$id);if(self::canRead($db,$who,$c))return;$q=$db->prepare("INSERT INTO contact_access(contact_id,principal,requester_name,status,requested_at,seen) VALUES(?,?,?,'pending',?,0) ON CONFLICT(contact_id,principal) DO UPDATE SET status='pending',requested_at=excluded.requested_at,seen=0 WHERE contact_access.status<>'pending' AND contact_access.requested_at<?");$q->execute([$id,$who['principal'],$who['name'],gmdate('c'),gmdate('c',time()-60)]);
 }
 public static function people(\PDO $db): array {
  require_once dirname(__DIR__).'/Admin/Users.php';\TNL\Admin\Users::init($db);$people=[];foreach($db->query('SELECT id,display_name FROM users WHERE active=1')->fetchAll(\PDO::FETCH_ASSOC) as $u)$people[]=['principal'=>'employee:'.$u['id'],'name'=>$u['display_name']];foreach($db->query('SELECT id,username FROM admins')->fetchAll(\PDO::FETCH_ASSOC) as $u)$people[]=['principal'=>'admin:'.$u['id'],'name'=>$u['username'].' · administración'];return $people;
 }
 public static function decide(\PDO $db,array $who,int $id,string $target,string $decision): void {
  self::owned($db,$who,$id);if(!in_array($decision,['granted','denied','revoked'],true))throw new \InvalidArgumentException('Permiso inválido.');$people=array_column(self::people($db),'name','principal');if(!isset($people[$target])||$target===$who['principal'])throw new \InvalidArgumentException('Usuario no disponible.');$now=gmdate('c');$q=$db->prepare('INSERT INTO contact_access(contact_id,principal,requester_name,status,requested_at,decided_at,seen) VALUES(?,?,?,?,?,?,0) ON CONFLICT(contact_id,principal) DO UPDATE SET status=excluded.status,decided_at=excluded.decided_at,seen=0');$q->execute([$id,$target,$people[$target],$decision,$now,$now]);
 }
 public static function permissions(\PDO $db,array $who,int $id): array {self::owned($db,$who,$id);$q=$db->prepare('SELECT * FROM contact_access WHERE contact_id=? ORDER BY requested_at DESC');$q->execute([$id]);return $q->fetchAll(\PDO::FETCH_ASSOC);}
 public static function notifications(\PDO $db,array $who): int {self::init($db);$q=$db->prepare("SELECT count(*) FROM contact_access a JOIN address_contacts c ON c.id=a.contact_id WHERE (c.owner=? AND a.status='pending' AND c.private=1) OR (a.principal=? AND a.status<>'pending' AND a.seen=0)");$q->execute([$who['principal'],$who['principal']]);return (int)$q->fetchColumn();}
 public static function requests(\PDO $db,array $who): array {self::init($db);$q=$db->prepare("SELECT a.*,c.first_name,c.last_name,c.company,c.owner FROM contact_access a JOIN address_contacts c ON c.id=a.contact_id WHERE (c.owner=? AND a.status='pending' AND c.private=1) OR a.principal=? ORDER BY a.requested_at DESC LIMIT 100");$q->execute([$who['principal'],$who['principal']]);return $q->fetchAll(\PDO::FETCH_ASSOC);}
 public static function seen(\PDO $db,array $who): void {self::init($db);$db->prepare("UPDATE contact_access SET seen=1 WHERE principal=? AND status<>'pending'")->execute([$who['principal']]);}
 public static function importCsv(\PDO $db,array $who,string $csv,bool $private=false): int {
  if(strlen($csv)>1048576||str_contains($csv,"\0")||!preg_match('//u',$csv))throw new \InvalidArgumentException('Usa un CSV UTF-8 de hasta 1 MB.');$f=fopen('php://temp','r+');fwrite($f,preg_replace('/^\xEF\xBB\xBF/','',$csv));rewind($f);$line=strtok($csv,"\n")?:'';$delimiter=substr_count($line,';')>substr_count($line,',')?';':',';$header=fgetcsv($f,0,$delimiter,'"','');if(!$header)throw new \InvalidArgumentException('El CSV no contiene encabezados.');$aliases=['nombre'=>'first_name','nombres'=>'first_name','firstname'=>'first_name','apellido'=>'last_name','apellidos'=>'last_name','lastname'=>'last_name','empresa'=>'company','company'=>'company','cargo'=>'job_title','jobtitle'=>'job_title','email'=>'email','correo'=>'email','correoelectronico'=>'email','telefono'=>'phone','phone'=>'phone','privado'=>'private','private'=>'private'];$keys=[];foreach($header as $key)$keys[]=$aliases[self::normalized($key)]??'';foreach(['first_name','last_name','company','job_title','email'] as $required)if(!in_array($required,$keys,true))throw new \InvalidArgumentException('Falta una columna obligatoria: '.$required);
  self::init($db);$count=0;$db->beginTransaction();try{while(($row=fgetcsv($f,0,$delimiter,'"',''))!==false){if(count($row)===1&&trim($row[0]??'')==='')continue;if(++$count>500)throw new \InvalidArgumentException('Máximo 500 contactos por importación.');$input=[];foreach($keys as $i=>$key)if($key!=='')$input[$key]=preg_replace("/^'(?=[\\s]*[=+@-])/u",'',(string)($row[$i]??''));$input['private']=$private||in_array(strtolower(trim($input['private']??'')),['1','true','si','sí','private','privado'],true);try{self::save($db,$who,0,$input);}catch(\InvalidArgumentException $e){throw new \InvalidArgumentException('Fila '.($count+1).': '.$e->getMessage());}}$db->commit();return $count;}catch(\Throwable $e){$db->rollBack();throw $e;}finally{fclose($f);}
 }
 public static function exportCsv(\PDO $db,array $who): string {
  if($who['role']!=='admin')throw new \InvalidArgumentException('Solo administración puede exportar contactos.');self::init($db);$q=$db->prepare("SELECT c.* FROM address_contacts c WHERE c.private=0 OR c.owner=? OR EXISTS(SELECT 1 FROM contact_access a WHERE a.contact_id=c.id AND a.principal=? AND a.status='granted') ORDER BY c.id LIMIT 10001");$q->execute([$who['principal'],$who['principal']]);$rows=$q->fetchAll(\PDO::FETCH_ASSOC);if(count($rows)>10000)throw new \InvalidArgumentException('La exportación supera 10 000 contactos.');$f=fopen('php://temp','r+');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['Nombre','Apellido','Empresa','Cargo','Correo','Telefono','Privado'],',','"','');foreach($rows as $c){$cells=[$c['first_name'],$c['last_name'],$c['company'],$c['job_title'],$c['email'],$c['phone'],(string)$c['private']];$cells=array_map(fn($v)=>preg_match('/^[\s]*[=+@-]/u',$v)?"'".$v:$v,$cells);fputcsv($f,$cells,',','"','');}rewind($f);$csv=stream_get_contents($f);fclose($f);return $csv;
 }
}
